const btnSave = document.getElementById('btn-save');
const btnDark = document.getElementById('btn-dark');
if (!btnSave || !btnDark) return false;

const isEnabled = !!document.getElementById('ai4a11y-focus-locator-styles');
if (!isEnabled) return true;

function getLuminance(rgbStr) {
  const m = rgbStr.match(/\d+/g);
  if (!m) return null;
  const [r, g, b] = m.slice(0, 3).map(v => {
    const c = Number(v) / 255;
    return c <= 0.03928 ? c / 12.92 : Math.pow((c + 0.055) / 1.055, 2.4);
  });
  return 0.2126 * r + 0.7152 * g + 0.0722 * b;
}
function contrast(c1, c2) {
  const l1 = getLuminance(c1);
  const l2 = getLuminance(c2);
  if (l1 === null || l2 === null) return null;
  return (Math.max(l1, l2) + 0.05) / (Math.min(l1, l2) + 0.05);
}

btnSave.focus();
const saveOutline = window.getComputedStyle(btnSave).outlineColor;
const ratioWhite = contrast(saveOutline, 'rgb(255, 255, 255)');
btnSave.blur();

btnDark.focus();
const darkOutline = window.getComputedStyle(btnDark).outlineColor;
const ratioDark = contrast(darkOutline, 'rgb(45, 55, 72)');
btnDark.blur();

return ratioWhite !== null && ratioWhite >= 3.0 &&
       ratioDark !== null && ratioDark >= 3.0;
